import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// 1. Blog Posts Collection
const posts = defineCollection({
  loader: glob({ pattern: '**/[^_]*.{md,mdx}', base: "./src/content/posts" }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    date: z.coerce.date(),
    category: z.string().optional(),
    readTime: z.string().optional(),
    image: z.string().optional(),
    tags: z.array(z.string()).default([]),
  }),
});


// 2. Imaging Projects (generated by `npm run import:trilium`)
const projects = defineCollection({
  loader: glob({
    pattern: '*/index.md',
    base: "./src/content/projects",
    generateId: ({ entry }) => entry.split('/')[0],
  }),
  schema: z.object({
    title: z.string(),
    camera: z.string().optional(),
    mount: z.string().optional(),
    telescope: z.string().optional(),
    acquisitionSoftware: z.string().optional(),
    coverImage: z.string().optional(),
    coverCaption: z.string().optional(),
    images: z.array(z.string()).default([]),
    acquisition: z.array(z.object({
      filter: z.string(),
      captured: z.number().optional(),
      planned: z.number().optional(),
      status: z.string().optional(),
      log: z.array(z.object({ night: z.string(), count: z.number() })).default([]),
      notes: z.string().optional(),
    })).default([]),
    sessionCount: z.number().default(0),
  }).loose(),
});

// 3. Imaging Sessions, one per night, grouped under their project
const sessions = defineCollection({
  loader: glob({ pattern: '*/sessions/*.md', base: "./src/content/projects" }),
  schema: z.object({
    title: z.string(),
    project: z.string(),
    date: z.coerce.date(),
    location: z.string().optional(),
    temperature: z.number().optional(),
    bortle: z.number().optional(),
    moonPhase: z.number().optional(),
  }).loose(),
});

export const collections = { posts, projects, sessions };